# Generated by Claude
"""Download metadata for every playlist on your YouTube account (plus the
videos in each one) via the YouTube Data API v3 and pickle it locally.

No video files are downloaded, only what the API returns (ids, titles,
descriptions, thumbnails, publish dates, status, etc.).  The URL for a video
is built from its videoId.
"""
import datetime
from dotenv import load_dotenv
import os
from pathlib import Path
import pickle

import httplib2
import google_auth_httplib2
import google_auth_oauthlib.flow
import googleapiclient.discovery
import googleapiclient.errors

load_dotenv()

os.environ['OAUTHLIB_INSECURE_TRANSPORT'] = '1'
scopes = ['https://www.googleapis.com/auth/youtube']
client_secret_file = Path(__file__).parent / os.getenv('CSF')

OUTPUT_FILE = 'youtube_playlists.pkl'
MAX_RESULTS = 50  # the API maximum for these endpoints
HTTP_TIMEOUT = 30  # seconds to wait on a socket before giving up
NUM_RETRIES = 5    # retries (with backoff) per request on timeouts/5xx/resets
MAX_EMPTY_PAGES = 2  # consecutive empty pages that mean "the list is over"

PLAYLIST_PARTS = ['contentDetails', 'id', 'snippet', 'status', 'player']
ITEM_PARTS = ['contentDetails', 'id', 'snippet', 'status']
SUBSCRIPTION_PARTS = ['contentDetails', 'id', 'snippet', 'subscriberSnippet']


def get_service():
    flow = google_auth_oauthlib.flow.InstalledAppFlow.from_client_secrets_file(
        client_secret_file, scopes)
    credentials = flow.run_local_server(port=0)
    # httplib2 has no timeout by default, so a stalled connection blocks
    # forever; with one, it raises socket.timeout and execute() can retry it.
    http = google_auth_httplib2.AuthorizedHttp(
        credentials, http=httplib2.Http(timeout=HTTP_TIMEOUT))
    return googleapiclient.discovery.build('youtube', 'v3', http=http)


def fetch_all(list_method, label=None, **kwargs):
    """Call a paginated API list method until the results are exhausted.

    Do NOT trust nextPageToken alone: for playlists containing hidden items
    (private/deleted videos) the API reports a totalResults larger than what
    can ever be fetched and keeps returning a nextPageToken on empty pages
    forever.  So paging stops when any of these is true:
      * there is no nextPageToken, or
      * we already hold totalResults items, or
      * the token repeats (the API is looping), or
      * MAX_EMPTY_PAGES pages in a row came back empty.
    """
    items = []
    page_token = None
    seen_tokens = set()
    empty_pages = 0
    page = 0
    while True:
        page += 1
        request = list_method(pageToken=page_token, maxResults=MAX_RESULTS, **kwargs)
        response = request.execute(num_retries=NUM_RETRIES)
        page_items = response.get('items', [])
        items.extend(page_items)
        total = response.get('pageInfo', {}).get('totalResults')
        if label:
            print(f'    {label}: page {page}, {len(items)}/{total if total is not None else "?"} items',
                  flush=True)

        page_token = response.get('nextPageToken')
        empty_pages = 0 if page_items else empty_pages + 1
        if (not page_token
                or page_token in seen_tokens
                or empty_pages >= MAX_EMPTY_PAGES
                or (total is not None and len(items) >= total)):
            break
        seen_tokens.add(page_token)
    return items


def fetch_playlist_items(service, playlist_id, label=None):
    """All videos in one playlist, each with a convenience 'url' field added."""
    items = fetch_all(service.playlistItems().list,
                      label=label, part=ITEM_PARTS, playlistId=playlist_id)
    for item in items:
        video_id = item.get('contentDetails', {}).get('videoId')
        item['url'] = f'https://www.youtube.com/watch?v={video_id}' if video_id else None
    return items


def fetch_subscriptions(service, label=None):
    """Every channel the user is subscribed to, each with a convenience 'url'.

    The channel being subscribed to is snippet.resourceId.channelId; the
    snippet also holds its title, description and thumbnails, and
    contentDetails has its total/new video counts.
    """
    subs = fetch_all(service.subscriptions().list, label=label,
                     part=SUBSCRIPTION_PARTS, mine=True)
    for sub in subs:
        channel_id = sub.get('snippet', {}).get('resourceId', {}).get('channelId')
        sub['url'] = f'https://www.youtube.com/channel/{channel_id}' if channel_id else None
    return subs


def fetch_special_playlist_ids(service):
    """Liked videos / uploads aren't returned by playlists().list(mine=True);
    their ids come from the channel's relatedPlaylists.

    Note: 'watchLater' and 'watchHistory' are returned as ids but the API
    no longer lets you read them (they come back empty or forbidden).
    """
    channels = fetch_all(service.channels().list,
                         part=['contentDetails'], mine=True)
    related = {}
    for channel in channels:
        related.update(channel['contentDetails'].get('relatedPlaylists', {}))
    return {name: pid for name, pid in related.items() if name in ('likes', 'uploads')}


def append_record(path, record):
    """Append one pickled record to the file and force it to disk.

    pickle.dump can be called repeatedly on the same open file; each call
    writes an independent object, and they are read back in order with
    repeated pickle.load calls.  Flushing + fsync after every record means a
    crash, Ctrl-C or hung connection loses at most the playlist in progress.
    """
    with open(path, 'ab') as f:
        pickle.dump(record, f)
        f.flush()
        os.fsync(f.fileno())


def load_records(path):
    """Yield every record in the file, in the order they were written.

    A crash mid-write can leave a truncated final record; that is ignored
    rather than raised, so everything before it is still usable.
    """
    with open(path, 'rb') as f:
        while True:
            try:
                yield pickle.load(f)
            except EOFError:
                return
            except pickle.UnpicklingError:
                print('Warning: ignoring truncated record at end of file')
                return


def load_backup(path):
    """Read the append-style file back into one dict:
    {'retrieved_at', 'complete', 'playlists', 'special_playlists',
    'subscriptions', 'errors'}
    """
    data = {'retrieved_at': None, 'complete': False,
            'playlists': [], 'special_playlists': {}, 'subscriptions': [],
            'errors': []}
    for rec in load_records(path):
        kind = rec['type']
        if kind == 'header':
            data['retrieved_at'] = rec['retrieved_at']
        elif kind == 'playlist':
            data['playlists'].append(rec['data'])
        elif kind == 'special':
            data['special_playlists'][rec['name']] = {'id': rec['id'], 'videos': rec['videos']}
        elif kind == 'subscriptions':
            data['subscriptions'] = rec['data']
        elif kind == 'error':
            data['errors'].append(rec)
        elif kind == 'complete':
            data['complete'] = True
    return data


def main():
    service = get_service()

    # start a fresh file for this run, then only ever append to it
    with open(OUTPUT_FILE, 'wb'):
        pass
    append_record(OUTPUT_FILE, {
        'type': 'header',
        'retrieved_at': datetime.datetime.now(datetime.timezone.utc).isoformat(),
    })

    # 1. every playlist the user owns
    try:
        playlists = fetch_all(service.playlists().list,
                              part=PLAYLIST_PARTS, mine=True)
    except (googleapiclient.errors.HttpError, OSError) as e:
        print(f'  ! could not list playlists: {e}')
        append_record(OUTPUT_FILE, {'type': 'error', 'playlist_id': None,
                                    'title': 'playlist list', 'error': str(e)})
        playlists = []

    print(f'Found {len(playlists)} playlists')

    # 2. every video in each playlist; each playlist is saved as soon as it is done
    for playlist in playlists:
        title = playlist['snippet']['title']
        try:
            playlist['videos'] = fetch_playlist_items(service, playlist['id'], label=title)
        except (googleapiclient.errors.HttpError, OSError) as e:
            # record the failure instead of saving an empty playlist that
            # would look like a successful (but empty) download
            print(f'  ! could not read "{title}": {e}')
            append_record(OUTPUT_FILE, {'type': 'error', 'playlist_id': playlist['id'],
                                        'title': title, 'error': str(e)})
            continue
        append_record(OUTPUT_FILE, {'type': 'playlist', 'data': playlist})
        got = len(playlist['videos'])
        expected = playlist['contentDetails']['itemCount']
        note = f' ({expected - got} hidden by the API: private/deleted)' if got < expected else ''
        print(f'  {title}: {got} videos (saved){note}')

    # 3. special playlists (liked videos, uploads), also saved one at a time
    try:
        special_ids = fetch_special_playlist_ids(service)
    except (googleapiclient.errors.HttpError, OSError) as e:
        print(f'  ! could not look up liked/uploads playlists: {e}')
        append_record(OUTPUT_FILE, {'type': 'error', 'playlist_id': None,
                                    'title': 'special playlist lookup', 'error': str(e)})
        special_ids = {}
    for name, pid in special_ids.items():
        try:
            videos = fetch_playlist_items(service, pid, label=name)
        except (googleapiclient.errors.HttpError, OSError) as e:
            print(f'  ! could not read [{name}]: {e}')
            append_record(OUTPUT_FILE, {'type': 'error', 'playlist_id': pid,
                                        'title': name, 'error': str(e)})
            continue
        append_record(OUTPUT_FILE, {'type': 'special', 'name': name,
                                    'id': pid, 'videos': videos})
        print(f'  [{name}]: {len(videos)} videos (saved)')

    # 4. channels the user is subscribed to
    try:
        subscriptions = fetch_subscriptions(service, label='subscriptions')
    except (googleapiclient.errors.HttpError, OSError) as e:
        print(f'  ! could not read subscriptions: {e}')
        append_record(OUTPUT_FILE, {'type': 'error', 'playlist_id': None,
                                    'title': 'subscriptions', 'error': str(e)})
    else:
        append_record(OUTPUT_FILE, {'type': 'subscriptions', 'data': subscriptions})
        print(f'  subscriptions: {len(subscriptions)} channels (saved)')

    # 5. marker so a later load can tell a finished run from an interrupted one
    append_record(OUTPUT_FILE, {'type': 'complete'})
    print(f'Saved to {OUTPUT_FILE}')


if __name__ == '__main__':
    main()
